<form class="card filters" method="get" action="<?= $e($url('/moderation')) ?>"><div><label for="status">Status</label><select id="status" name="status"><option value="">All</option><?php foreach (['OPEN','REVIEWED','DISMISSED'] as $s): ?><option<?= $status === $s ? ' selected' : '' ?>><?= $e($s) ?></option><?php endforeach; ?></select></div><button class="btn" type="submit">Filter</button></form>
<div class="card"><table><thead><tr><th>ID</th><th>Reporter</th><th>Reported user</th><th>Reason</th><th>Status</th><th>Review</th></tr></thead><tbody>
<?php if (!$rows): ?><tr><td colspan="6" class="muted">No reports.</td></tr><?php endif; ?>
<?php foreach ($rows as $r): ?><tr><td><?= $e($r['id']) ?></td><td><?= $e($r['reporter']) ?></td><td><?= $e($r['reported']) ?> <?= $badge($r['reported_status']) ?></td><td><?= $e($r['reason']) ?><?= $r['admin_note'] ? '<br><span class="muted">Note: ' . $e($r['admin_note']) . '</span>' : '' ?></td><td><?= $badge($r['status']) ?></td>
<td><?php if ($r['status'] === 'OPEN'): ?><form method="post" action="<?= $e($url('/moderation/' . $r['id'])) ?>"><?= $csrf() ?><input name="admin_note" placeholder="Note (optional)" maxlength="1000" aria-label="Admin note"><div class="row"><button class="btn small" name="status" value="REVIEWED">Mark reviewed</button><button class="btn small secondary" name="status" value="DISMISSED">Dismiss</button></div></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?>
</tbody></table><?= $pagerHtml ?></div>
<p class="muted">To act on a reported account use the <a href="<?= $e($url('/users')) ?>">Users</a> page (suspend / reactivate).</p>
